from author_library import *
cards=[]
cards.append(compact('ding_zhen','丁真','丁真三十岁出头，已经凭多项发明、专利和学位获得声望与财富，被陶氏集团聘来主持研究室。他有年轻成功者的英气，却一样会失恋，也一样会因醉酒判断失当。雨夜站在道路上没有及时避让，他使运鸡货车翻覆，自己只受轻伤，司机却骨折。事后他首先承认责任，拄杖等候对方手术结束，提出承担一切赔偿；这份担当并非为了讨好媒体。后来，他迷恋看似何可人的女子，把替她寻回每一只鸡当成必须完成的大事，愿意耗费资源，也不愿正视旁人对她身份的怀疑。他作为发明家擅长技术，并不因此擅长爱情，更不能凭智力摆脱对方的吸引。故事末他终于抱回三六五号母鸡，兴奋地向屋内报喜，却没有参加白素与纳塔莎的私下谈话，不知道原何可人早已死亡，也不知道自己追求的人与公鸡是情侣。卡片保留他的负责、热忱和专注，同时保留知识上的巨大缺口。演绎中，他可以把一件小事当成郑重承诺去完成，也可以在亲近者的请求与事实核验之间产生犹豫；不能因旁白称其大发明家就随手创造未在原文出现的超技术。','找到走失母鸡后仍追随何可人外貌的女子；未证实得知纳塔莎身份或恋情获回应','主角','履行自己造成事故后的责任，并争取所爱之人的认可','认真投入研究或具体任务，有能力调动个人资金和专业团队','觉得自己欠下人情时容易把对方要求看得绝对重要，忽略旁人的警告','技术成就不等于情感判断无误，赔偿责任与求爱愿望可能交织',[ab('发明研究与资源组织','有多项实际发明和专利，受聘主持陶氏研究室，能协调寻物','本书未给出可直接作战的具体发明，不授予任意制造能力')],[ev('115',71,99,'身份成就、财富和承认交通责任'),ev('115',143,188,'医院等候、愿意补偿的选择'),ev('115',593,628,'追寻母鸡并显露迷恋'),ev('115',2673,2677,'找到母鸡后的最后行动')],profile='expert',extra={'appearance':{'description':'三十多岁，身形挺拔，不以俊朗著称而有英气；车祸后脚踝受伤曾用拐杖。','portrayal':'一旦认定应负责的事，语气急切而郑重。'}}))
cards.append(compact('he_keren_original','何可人（原本人）','原来的何可人出身社会福利照护体系，少年时未读完中学便进入何氏鸡场工作。她长期独自打理鸡群、运输和日常事务，把场地照料得整齐，劳动辛苦却换得相对自由的生活。她对鸡有感情，送鸡去市场会难过，还挑出几只作为宠物，不肯让老人随便宰杀。外人起初把她与何正汉的关系想成亲如祖孙，甚至用这一印象责备车祸中的何可人只惦记鸡、不惦记老人；后来才知道，表面的慈爱是误导。何正汉以威迫、利诱、药物和持刀相胁企图侵犯她，最终在一次强迫中将她杀死。公鸡阿大目睹后啄死了他，纳塔莎则怜惜这个遭遇冤屈的女子，借用她的身体和名字继续生活。因此，小说开篇车祸、寻鸡和与丁真相处的行为，都不能直接算给原本人。她的死亡发生于主要调查之前，真实年龄在材料中还有二十二与二十四的差异。本卡保存劳动者和受害者本人的身份，允许按最后可行动的人类形态参与新故事，却不夺取纳塔莎的记忆、变化本领或对阿大的情侣关系。她与鸡的亲近，是有证据的日常情感，不是凭空出现的万兽通灵。','被何正汉在强迫行为中杀害，原本人未复活；后续同貌同名者为纳塔莎','主角','维持自食其力的生活，照顾珍爱的动物并抵抗侵犯自身意愿的安排','认真管理鸡场，对亲手养大的动物有感情','被迫放弃自己珍惜的生命或遭人强迫时会抗拒，不把施害者的恩惠当作服从义务','把具体照护和自己的生活自主看得重要，未证实拥有后来借身者的知识',[ab('鸡场劳作与照护','长期负责鸡场日常工作，具饲养、管理和运输经验','普通人类技能；没有证实可听懂所有动物语言或改变生命形式')],[ev('115',872,887,'少年进入鸡场及多年劳作'),ev('115',949,975,'日常照护、爱惜宠物及与老人争执的回述'),ev('115',2684,2709,'遭杀害、阿大报仇与纳塔莎借身的终局解释')],profile='ordinary',extra={'uncertainties':['资料中年龄有二十二与二十四的差异，不能以此拆作两个原本人。','原本人死亡后的车祸、寻鸡、与丁真交往属于纳塔莎，不迁移到本卡。']}))
cards[-1]['version']['deployment']='明确恢复最后可行动的人类形态并保留终局记忆；纳塔莎借身形态与此卡互斥，不叠加同一身体的两个行动主体。'
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆。','reason':'让原本人仍能作为独立人物行动，不把借身写成本人复活。','power_impact':'无新增超常能力，不继承借身者知识。'})
cards.append(compact('natasha','纳塔莎','纳塔莎来自何处、原本是哪一种生命，白素最终也没有追问。她被鸡场能改变生命形式的奇异力量吸引，远道而来，在何可人被杀后借用其身体和姓名生活，又与已经发生变化的公鸡阿大结成情侣。她认为五百六十只正在变化的母鸡可能为害，于是逐一编号送往市场宰杀；车祸使它们四散，她受伤后仍急切追索，焦虑并非出于普通财产损失。这种先行消灭风险的决定有保护人类的意图，也有未经个体行为便代作生死判断的冷酷，不能简单写成温柔动物守护者。她能用人类身份、法律语言与警方争辩，面对黄堂威胁阿大时挺身挡在枪前；同时，她借用的身体会骨折、疼痛，需要手术、石膏和拐杖。神鹰出现后，她与阿大退回屋中，接受白素单独谈话，解释来历的一部分，把鸡场交给白素并准备离开。对于唯一逃过宰杀的母鸡，她改以因果有缘解释，允许留下研究。终局保存的是一个愿意保护伴侣、重视私生活、也会为公共风险做强硬选择的异类；她并没有向读者展示自己的完整原形，更没有证明可无条件控制鸡场的时间异常。','向白素交出鸡场并与阿大准备离开；人类借身仍曾受车祸骨折，原形不明','主角','保护与阿大的生活，避免鸡场变化扩散造成她所担心的祸害','以何可人身份管理鸡场，能用常人社会规则维护边界','伴侣受直接威胁时站出来保护；局势不利时愿意私下谈判并迁离','异类不必天然与人为敌，但她也可能以预防危险为由作出过度决定',[ab('借用人类身体生活','在何可人死亡后进入其身体，继续使用姓名与社会身份','这是她已展示的形态；不能据此夺取活人、无限换身或自动复活别人',kind='生命形式'),ab('理解鸡场变化与交流','能与阿大协调，识别鸡群进入变化期并采取管理措施','不等于她制造了场地力量；未证实能关闭时间漩涡或控制所有动物')],[ev('115',219,250,'身体的伤势、痛觉和强力要求寻鸡'),ev('115',2531,2565,'保护阿大并用法律反驳'),ev('115',2614,2677,'退避神鹰、私谈与准备离开'),ev('115',2684,2743,'借身身份、与阿大的关系、鸡场交出及名字')],profile='ordinary',aliases=['何可人（借身时期）'],extra={'baseline':{'mind':'具有异类生命经验，完整意识机制未知；没有精神控制免疫证据。'},'uncertainties':['纳塔莎与神鹰所畏惧的纳塔之蛇存在名字与表现关联，原文没有展示原形，保留未证实。','可自行幻化或借身为白素转述的一般解释，纳塔莎直接展示的是借身，不把所有变化路线都当可随时发动。']}))
rate(cards[-1],[2,0,1,2,1,3],neg=(2,2,1),tier='并',reason='借身者有一定力量和判断，仍会骨折受伤；未知原形不换算战斗分')
cards.append(compact('ada_rooster','阿大（公鸡）','阿大是何氏鸡场中因奇异环境逐渐改变生命形式的公鸡，有红色身影和远超普通家禽的行动力量。它与原何可人的生活相连，目睹何正汉杀害她后，用尖喙啄穿老人喉部和太阳穴，形成警方无法解释的窄缝命案。纳塔莎借用死者身体以后，与阿大成为情侣；这层关系不能倒写成原何可人与鸡相恋。面对调查者，阿大会主动攻击，抓伤黄堂、躲开踢击，并在对方拔枪时迅速藏到纳塔莎身后。神鹰出现，它没有像普通鸡那样逃跑，而是腾起数米迎战，双方掉落羽毛后分开；神鹰仍有优势，阿大和纳塔莎最终退入屋中。文本说它将来道行足够可以变成人，但终局并未发生，所以本卡仍以公鸡形态行动。它表现出识别威胁、协作保护和记忆仇人的能力，却没有被证实能说人话或远距施法。新场景里，它可以让保护伴侣的冲动压过谨慎，也可以在对手明显占优时听从退让，不必每次以一场鸣叫决斗证明身份。鸡场变异是经历来源，不能让它离开鸡场后随意创造同样的场地力量。','与纳塔莎准备离开鸡场，保持公鸡形态；变成人只是未来可能，未实际完成',['主角','阶段性对立者'],'保护纳塔莎以及自己认定的亲近者，抵抗捕杀','以鸣叫、位置和动作与伴侣协作，对陌生接近保持戒备','见到直接伤害或持械威胁会猛扑反击，遇更强对手也会随伴侣退入安全处','有主动性和关系记忆，但不因此预知人类的全部计划',[ab('强化喙爪与短距扑击','喙伤可穿人体要害，腾跃数米，抓伤并躲开高手动作','仍为有羽毛与肉体的鸟，会在搏斗中掉羽受伤；未有枪弹免疫'),ab('伙伴协作','理解纳塔莎的行动，与她退避、借遮挡脱身','不是对所有生物的精神控制，没有已展示的人形变化')],[ev('115',1515,1613,'窄缝命案伤口与鸡喙推断'),ev('115',2539,2559,'攻击黄堂、闪避及退到伴侣身后'),ev('115',2578,2638,'腾空与神鹰交手、双方力量边界'),ev('115',2688,2709,'为原何可人复仇与纳塔莎情侣关系')],profile='martial',extra={'appearance':{'description':'红色公鸡，战斗时全身羽毛竖起，鸣声嘹亮。','portrayal':'以昂头、腾跃、鸣叫和贴近伴侣表达警戒，不添加未经展示的人语。'},'baseline':{'destruction':'强化鸡喙和爪可造成致命人体穿刺；不外推穿钢或建筑破坏。','durability':'禽鸟肉身，会掉羽和受创，未证实耐枪火、毒素或极端环境。','speed':'短距动作能与人类高手及神鹰周旋，腾起约三四公尺；持续飞行不如鹰。'}}))
cards.append(compact('hen_365','三六五号母鸡','这只翼尖带着三六五号标记的母鸡，本是纳塔莎决定送往市场的五百六十只鸡之一。鸡场的特殊环境让这批鸡进入生命变化初期，而纳塔莎担心它们完成变化后会作恶，于是提前安排宰杀；三六五号在运送事故中走失，成为唯一迟迟没有追回的目标。它被找到后，在神鹰和人类面前显示出异常反应：似乎能理解双方的语言，在有人谈及宰杀时悄悄睁眼，受到抓提和威吓却闭目垂脚装死。卫斯理与神鹰称它狡猾，但这种评价来自追捕者，不能直接证明它已经有伤害无辜的行为。它没有像阿大那样展示强大攻击，也没有变成人。最终丁真把它带回，纳塔莎认为它既然逃过一劫便有因果，允许白素留下研究。它的行为可以围绕求生、观察强者态度和隐藏自身理解力展开：当反抗明显无望时不动，比逞强更符合其已见表现；一旦得到喘息机会，也可以尝试避开看守。卡片保留它作为独立生命的不确定未来，不把“可能成精”直接变成已经掌握人形、法术或作恶天性。','唯一幸存的编号母鸡，获准留给白素研究；尚未证实变成人或具有阿大的力量','主角','躲开被宰杀的命运，尽可能保存自己的行动机会','观察谈话与动静，常隐藏自己的理解程度','面对强大捕捉者时闭目垂脚装死，减少立即反击而暴露的风险','别人认为它将来可能有害，不等于它已实施了那种行为',[ab('异常理解与装死','对人和鹰的言语表现有对应反应，受抓提仍维持不动','语言理解有观察支持，但完整思想未被直接读取；没有强攻、变形或法术展示')],[ev('115',593,599,'唯一未找回的三六五号'),ev('115',1731,1756,'理解人鹰言语的表现与装死'),ev('115',1801,1839,'保持不动及对谈话的反应'),ev('115',2673,2677,'丁真最终寻回'),ev('115',2715,2724,'变化初期、宰杀理由及例外留下')],profile='ordinary',extra={'baseline':{'destruction':'普通母鸡的喙爪，没有阿大级别攻击展示。','durability':'禽鸟肉身，仍受捕捉、伤害与宰杀威胁。','speed':'按母鸡奔跑、短距扑翅与躲藏，没有持续高速飞行证据。'}}))
cards.append(compact('he_zhenghan','何正汉','何正汉曾是中将军长，经历战争与权力更迭后失势，靠预先经营的鸡场维持晚年生活。卫斯理在鸡场的异常经历中见到一个衰老、行动不便、一天多没有进食的老人，替他饮食、喂鸡，也听他讲过去的辉煌与何可人的勤劳。老人把两人的关系说得像祖孙，称自己依赖这个年轻女子照护；这种叙述令卫斯理一度对不在场的她生出不满。后来警方资料指出老人早已死亡，尸体藏在水泥柱之间，脚印和手杖痕迹显示他亲自挤进去躲避某种追袭。真相经纳塔莎向白素说明：他曾以各种威迫和诱骗方式企图侵犯何可人，在一次强迫行动中杀死了她，继而被目睹惨剧的阿大啄死。他的军功和衰弱因此都不能抵消具体暴行，也不能用看似可怜的晚境替他抹去责任。原文把卫斯理见到已死老人的经历解释为鸡场时间漩涡的可能作用，老人本人没有展示复活或控时能力。本卡采用最后可行动的年老身体，保留自述习惯与施害事实，允许他在新场景中以恩惠、权威和受照顾者姿态试图影响别人，也明确这些手段会遭到识破和抵抗。','三年前被阿大啄死；后来出现属于场地时间异常的解释，非本人复活或控时','反派','在失势和衰老中维持对生活与身边人的控制，曾把照护关系转成侵犯','讲述昔日地位并强调自己需要照顾，容易将劳动者当作属于自己的资源','权威或欲望受到拒绝时可能威迫诱骗，不能因年老就排除其危害','社会地位和给予工作不构成他人必须服从的理由，原作暴行须保留',[ab('旧军旅与鸡场经营经验','有指挥和经营经历，年老时靠鸡场与何可人照护生活','最后形态行动不便，不能把早年军人巅峰体能或军队当作当前常备')],[ev('115',923,975,'衰老外观、军旅自述与依赖照护'),ev('115',1515,1586,'死亡现场、伤口与躲避轨迹'),ev('115',2684,2693,'强迫杀人和被阿大报仇'),ev('115',2729,2731,'场地时间异常解释')],profile='ordinary',extra={'appearance':{'description':'眼眶深陷、目光混浊、皱纹满面，双手青筋明显，需竹杖支撑。','portrayal':'说话费力又喜欢追叙往事，衰弱不自动意味着温和。'}}))
cards[-1]['version']['deployment']='明确恢复最后可行动的年老人类形态并保留终局记忆；保留行动不便，不恢复青年军人巅峰或个人控时能力。'
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆。','reason':'使已死反派可在新场景出现，同时保留原作死亡事实。','power_impact':'无新增权能，不附送军队、青春或鸡场异常。'})
save(cards)
